"""Base classes that are extended by low level AMQP frames and higher level
AMQP classes and methods.

"""


class AMQPObject(object):
    """Base object that is extended by AMQP low level frames and AMQP classes
    and methods.

    """
    NAME = 'AMQPObject'
    INDEX = None

    def __repr__(self):
        items = list()
        for key, value in self.__dict__.items():
            if getattr(self.__class__, key, None) != value:
                items.append('%s=%s' % (key, value))
        return 'AMQPObject(%s)' % (self.__class__.__name__, items)

    def __init__(self, *args, **kwargs):
        if not isinstance(args, list):
            self._args = [args]
        else:
            self._args = args
        if not isinstance(kwargs, dict):
            self._kwargs = {
                'key': kwargs.get('key'),
                'value': kwargs.get('value')
            }
        else:
            self._kwargs = kwargs
        self._args = args
        self._kwargs = kwargs

