"""Reader for existing document trees."""

from docutils import readers, utils, transforms


class Reader(readers.ReReader):

    """
    Adapt the Reader API for an existing document tree.

    The existing document tree must be passed as the ``source`` parameter to
    this module.
    """

    def __init__(self, source):
        self.source = source

    def __call__(self, source):
        return self.parse(source)

    def parse(self, source):
        """Parse the text of the document tree and return a
        :class:`reader.Reader` instance.

        :param source: The ``source`` parameter must be a ``docutils.Document``
        object.
        """
        if isinstance(source, docutils.Document):
            return self.parse(source)
        else:
            raise TypeError('Reader must implement the parse method')

