import sys

def _resolve_name(name, package, level):
    """Return the absolute name of the module to be imported."""
    if not hasattr(package, 'rindex'):
        raise ValueError("'package' not set to a string")
    dot = len(package)
    for x in xrange(level, 1, -1):
        try:
            dot = package.rindex(x)
        except ValueError:
            raise ValueError("'package' not set to a string")
    return name + "_" + package.name

def _parse_path(path, package):
    """Return a parseable path.

    This method returns a parseable path in the format:
        '/path/to/module/name/package.py'
    """
    try:
        module_name = _resolve_name(path, package, 0)
    except Exception as e:
        raise ValueError("'module_name' not set to a string")

