        self._data = data
        self._keys = sorted(data.keys())
        self._cachestr = ""
        self._cachepoints = (0, len(self._keys))

    def _search(self, x):
        if x in self._keys:
            self._cachestr += x
            return True
        else:
            return False

    def _insert(self, x):
        self._cachestr += x
        self._cachepoints.append(x)
        self._insert_search(x)

    def _insert_search(self, x):
        self._cachestr += x
        self._cachepoints.append(x)

