def _resolve_name(name, package, level):
    """Return the absolute name of the module to be imported."""
    if not hasattr(package, 'rindex'):
        raise ValueError("Unsupported package %s" % name)
    if not hasattr(package, 'rsplit'):
        raise ValueError("Unsupported package %s split %s" % (name, package))
    if level > 0:
        raise ValueError("Unsupported level %s" % level)
    return package.rindex(name, level)

