class ColdObservable(ObservableBase):
    def __init__(self, scheduler, messages):
        super(ColdObservable, self).__init__()

        self.scheduler = scheduler
        self.messages = messages
        self.subscriptions = AssertList()

    def subscribe(self, on_next=None, on_error=None, on_completed=None, on_complete=None):
        sub = Subscription()

        def on_next(value):
            if not on_next:
                return
            on_next(value)

        def on_error(value):
            if not on_error:
                return
            on_error(value)

        def on_completed(value):
            if not on_completed:
                return
            on_completed(value)

        def on_complete(value):
            if not on_complete:
                return
            on_complete(value)

        self.subscriptions.add(sub)
        return sub

