import tensorflow as tf

class Vanilla2DCell(tf.contrib.rnn.RNNCell):
    """Vanilla Recurrent Unit cell."""

    def __init__(self, num_units, channels):
        self._num_units = num_units
        self._channels = channels

    @property
    def state_size(self):
        return self._num_units

    @property
    def output_size(self):
        return self._num_units

    def make_var(self, name, shape, initializer=None, trainable=True):
        return tf.get_variable(name, shape, initializer=initializer, trainable=trainable)

    def construct(self, inputs, state, scope):
        outputs = tf.layers.dense(inputs, self._num_units,
                                    activation=tf.nn.relu,
                                    kernel_initializer=self.make_var('kernel', [self._num_units]),
                                    bias_initializer=self.make_var('bias', [self._num_units]))
        return outputs

    def call(self, inputs, state, scope):
        return self.construct(inputs, state, scope)

