class AMQPObject(object):
    """Base object that is extended by AMQP low level frames and AMQP classes
    and methods.

    """
    NAME = 'AMQPObject'
    INDEX = None

    def __repr__(self):
        items = list()
        for key, value in self.__dict__.items():
            if getattr(self.__class__, key, None) != value:
                items.append('%s=%s' % (key, value))
        return '%s(%s)' % (self.__class__.__name__, ','.join(items))

    def __init__(self, *args, **kwargs):
        """Constructor that is called by AMQP low level frames.

        """
        self.__dict__.update(kwargs)

    def __str__(self):
        """Conversion of AMQP object into string.

        """
        return self.__repr__()

