class Vanilla2DCell(tf.contrib.rnn.RNNCell):
    """Vanilla Recurrent Unit cell."""

    def __init__(self, num_units, channels):
        self._num_units = num_units
        self._channels = channels

    @property
    def state_size(self):
        return self._num_units

    @property
    def output_size(self):
        return self._num_units

    def make_var(self, name, shape, initializer=None, trainable=True):
        return tf.get_variable(name, initializer=initializer, shape=shape, trainable=trainable)

    def call(self, inputs, state):
        raise NotImplementedError()

    def zero_state(self, batch_size, dtype=tf.float32):
        return self.make_var('zeros', [batch_size, self._num_units], tf.zeros_initializer())

    def zero_output(self, state, dtype=tf.float32):
        return self.make_var('zeros', [self._num_units], tf.zeros_initializer())

